// ═══════════════════════════════════════════════════════════════════════
//  THE ONLY NODE YOU EDIT. Add one { … } block per page you want watched.
//  Save, and you are done — everything downstream adapts automatically.
// ═══════════════════════════════════════════════════════════════════════
//
//  url       REQUIRED. The page to watch. Must be server-rendered HTML — if
//            the content is painted by JavaScript the scan reports 'no
//            readable text' and you get one 'watch is blind' warning.
//
//  watch_id  REQUIRED. The key its snapshot is stored under. Keep it FIXED
//            once set — renaming it starts a fresh watch, which costs one
//            silent re-baseline. Letters, digits and underscores.
//
//  look_for  Optional. Comma-separated keywords; only new lines containing
//            one of them are reported. Turkish-folded, so 'sinav sonuc'
//            matches 'SINAV SONUÇLARI'. LEAVE EMPTY to report any new line —
//            right for a calendar page, too noisy for a news-style page.
//
//  ignore    Optional. Regex of lines to drop BEFORE diffing. This is the
//            knob that kills false alarms: clocks, visitor counters, 'son
//            güncelleme', rotating quotes. Add to it when a watch cries wolf.
//
//  agent     Optional, default 'speda'. Which agent composes the push —
//            'ultron' for academic, 'nightcrawler' for surveillance,
//            'sentinel' for money. The push arrives in that agent's voice.
//
const WATCHES = [

  // ── EXAMPLE — delete these two lines and put your own pages here ───────
  // { watch_id: 'akademik_takvim', url: 'https://ogrenci.uni.edu.tr/akademik-takvim',
  //   look_for: '', ignore: 'son güncelleme|ziyaretçi|©', agent: 'ultron' },

];

// ── Nothing below this line needs editing ───────────────────────────────
const out = [];
WATCHES.forEach((w, i) => {
  if (!w || !w.url || !w.watch_id) { return; }   // half-filled entry: skip, don't crash
  out.push({
    json: {
      watch_id: String(w.watch_id).trim(),
      url: String(w.url).trim(),
      look_for: w.look_for || '',
      ignore: w.ignore || '',
      max_added: w.max_added || 40,
      agent: (w.agent || 'speda').trim(),
    },
    pairedItem: { item: 0 },
  });
});
// An empty list returns no items, which stops the branch — so an unconfigured
// but ACTIVE workflow is harmless rather than an error every 30 minutes.
return out;

const store = $getWorkflowStaticData('global');
const broken = store.broken || {};
const cfg = $('Watch list').all();
const out = [];

$input.all().forEach((item, i) => {
  const res = item.json || {};
  // watch_id comes back in every Igor response, including its errors; the
  // config is the fallback for when the HTTP node itself failed.
  const id = res.watch_id || (cfg[i] && cfg[i].json.watch_id) || ('#' + i);
  const status = res.status || 'error';

  // ── Watch health, EDGE-triggered, PER PAGE ────────────────────────────
  // A site that 404s, blocks us, or moves to JS rendering leaves that watch
  // permanently blind while the workflow still looks green. Worth one push —
  // but only on the transition, and only for the page that broke.
  if (status === 'error') {
    if (!broken[id]) {
      broken[id] = true;
      out.push({ json: {
        alert: true, watch_id: id, url: res.url || (cfg[i] && cfg[i].json.url) || '',
        agent: (cfg[i] && cfg[i].json.agent) || 'speda',
        detail: res.detail || '', fingerprint: '', added: [], added_count: 0,
      }, pairedItem: { item: i } });
    }
    return;
  }
  broken[id] = false;

  // 'baseline' is a page's first sight: recorded, deliberately silent.
  if (status !== 'ok' || !res.changed) { return; }

  // ── Something was published ───────────────────────────────────────────
  out.push({ json: {
    alert: false,
    watch_id: id,
    url: res.url,
    title: res.title || '',
    agent: (cfg[i] && cfg[i].json.agent) || 'speda',
    fingerprint: res.fingerprint,
    added: res.added || [],
    added_count: res.added_count || 0,
    truncated: Boolean(res.truncated),
    removed_count: res.removed_count || 0,
  }, pairedItem: { item: i } });
});

store.broken = broken;
return out;
